-- Every resource (tool, prompt, template, video, ...) gets its own shareable
-- page at /resource/<slug>, like automations do. The slug is generated by a
-- trigger so every insert path (public form, admin forms) gets one.
alter table public.resources add column slug text;

create or replace function public.resources_set_slug()
returns trigger
language plpgsql
as $$
declare
  base text;
begin
  if new.slug is null or new.slug = '' then
    base := btrim(regexp_replace(lower(new.title), '[^a-z0-9]+', '-', 'g'), '-');
    if base = '' then base := 'resource'; end if;
    new.slug := left(base, 80) || '-' || substr(replace(new.id::text, '-', ''), 1, 6);
  end if;
  return new;
end;
$$;

create trigger trg_resources_set_slug
  before insert on public.resources
  for each row execute function public.resources_set_slug();

-- Backfill existing rows with the same rule.
update public.resources
set slug = left(coalesce(nullif(btrim(regexp_replace(lower(title), '[^a-z0-9]+', '-', 'g'), '-'), ''), 'resource'), 80)
           || '-' || substr(replace(id::text, '-', ''), 1, 6)
where slug is null;

alter table public.resources alter column slug set not null;
create unique index resources_slug_key on public.resources (slug);
